import * as T from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;document.body.append(renderer.domElement);
const scene=new T.Scene();scene.background=new T.Color(0x26343a);scene.add(new T.HemisphereLight(0xe9f8ff,0x93836b,1.7));
const sun=new T.DirectionalLight(0xffedda,3);sun.position.set(-3,5,4);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=sun.shadow.camera.bottom=-3;sun.shadow.camera.right=sun.shadow.camera.top=3;sun.shadow.normalBias=.01;scene.add(sun);
const floor=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshStandardMaterial({color:0xb6b09a,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.148;floor.receiveShadow=true;scene.add(floor);
const camera=new T.PerspectiveCamera(36,innerWidth/innerHeight,.02,100);camera.position.set(1.8,1.5,2.5);camera.lookAt(0,.1,.1);
const model=await new GLTFLoader().loadAsync('/assets/turtle.glb');model.scene.getObjectByName('TurtleLow')!.visible=false;scene.add(model.scene);const mixer=new T.AnimationMixer(model.scene),actions=model.animations.map(c=>mixer.clipAction(c));const render=()=>{model.scene.updateMatrixWorld(true);renderer.render(scene,camera);};
const views:Record<string,number[]>={front:[0,.45,2.8],side:[2.8,.55,0],top:[0,3.2,.04],threeQuarter:[1.7,1.6,2.3]};
(window as any).__turtle={ready:true,setView(name:string){camera.position.fromArray(views[name]);camera.lookAt(0,.10,0);render();},pose(name:string,t:number){actions.forEach(a=>a.stop());const a=actions.find(a=>a.getClip().name===name);if(a)a.play();mixer.setTime(t);render();},orbit(a:number){camera.position.set(Math.sin(a)*2.9,1.4,Math.cos(a)*2.9);camera.lookAt(0,.1,0);render();},motion(t:number){const smooth=(a:number,b:number)=>{const x=T.MathUtils.clamp((t-a)/(b-a),0,1);return x*x*(3-2*x);},crawl=smooth(5.8,6.25),idle=smooth(11.8,12.25);actions.forEach(a=>{a.play();a.setEffectiveWeight(a.getClip().name==='Swim'?1-crawl:a.getClip().name==='Crawl'?crawl*(1-idle):idle);});mixer.setTime(t);render();},render,renderer,scene,camera,model,mixer,actions};
render();
